<?php
require_once __DIR__ . '/../database/app/layout.php';
$u=require_role(['admin','restaurant','event_organizer','ngo','demand_reporter']);$pdo=db();
$start=trim((string)($_GET['start']??date('Y-m-01')));$end=trim((string)($_GET['end']??date('Y-m-d')));$format=(string)($_GET['format']??'view');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)||$start>$end){http_response_code(400);exit('Invalid date range.');}
$where="DATE(dr.updated_at) BETWEEN ? AND ? AND dr.status IN ('delivered','completed')";$args=[$start,$end];
if($u['role']==='admin'){}elseif(in_array($u['role'],['restaurant','event_organizer'],true)){$where.=' AND sf.restaurant_id=?';$args[]=$u['id'];}else{$where.=' AND dr.requested_by=?';$args[]=$u['id'];}
$q=$pdo->prepare("SELECT dr.id AS request_id,dr.status,dr.quantity_kg,dr.created_at,dr.updated_at,sf.id AS food_id,sf.food_name,sf.category,sf.safety_deadline,donor.name AS donor,recipient.name AS recipient,d.status AS delivery_status,d.delivery_time FROM donation_requests dr JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users donor ON donor.id=sf.restaurant_id JOIN users recipient ON recipient.id=dr.requested_by LEFT JOIN deliveries d ON d.donation_request_id=dr.id WHERE $where ORDER BY dr.updated_at DESC LIMIT 5000");$q->execute($args);$rows=$q->fetchAll();
if($format==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="foodrescue-report-'.$start.'-'.$end.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Request ID','Food ID','Food','Category','Quantity kg','Donor','Recipient','Request status','Delivery status','Safety deadline','Delivery time']);foreach($rows as $r){$cells=[$r['request_id'],$r['food_id'],$r['food_name'],$r['category'],$r['quantity_kg'],$r['donor'],$r['recipient'],$r['status'],$r['delivery_status'],$r['safety_deadline'],$r['delivery_time']];foreach($cells as &$cell){if(is_string($cell)&&preg_match('/^[=+\-@\t\r]/',$cell))$cell="'".$cell;}unset($cell);fputcsv($out,$cells);}fclose($out);exit;
}
page_header('Report builder'); ?>
<div class="page-intro"><div class="eyebrow">EXPORT & REPORTING</div><h1>Report <em>builder.</em></h1><p>Generate a date-bounded CSV of completed donation requests visible to your account. Export is capped at 5,000 records.</p></div>
<form method="get" class="filter-bar"><label>From <input type="date" name="start" value="<?= e($start) ?>" required></label><label>To <input type="date" name="end" value="<?= e($end) ?>" required></label><button class="btn" name="format" value="view">Preview</button><button class="btn btn-light" name="format" value="csv">Download CSV</button></form>
<div class="table-wrap"><table><thead><tr><th>Request</th><th>Food</th><th>Quantity</th><th>Donor</th><th>Recipient</th><th>Delivery</th><th>Updated</th></tr></thead><tbody><?php foreach(array_slice($rows,0,100) as $r): ?><tr><td>#<?= (int)$r['request_id'] ?></td><td><?= e($r['food_name']) ?><small class="table-sub"><?= e($r['category']) ?></small></td><td><?= e((string)$r['quantity_kg']) ?> kg</td><td><?= e($r['donor']) ?></td><td><?= e($r['recipient']) ?></td><td><?= e($r['delivery_status']??'—') ?></td><td><?= e((string)$r['updated_at']) ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="table-empty">No completed requests in this period.</td></tr><?php endif; ?></tbody></table></div><p class="table-sub">Showing up to 100 preview rows from <?= count($rows) ?> exportable records. Export includes a spreadsheet-formula injection mitigation for text fields.</p>
<?php page_footer(); ?>
